     chk("prompt_version", "content", "char_length(content_text) BETWEEN 20 AND 20000 AND content_text !~ '([0-9]{1,3}\\.){3}[0-9]{1,3}' AND content_text !~* '(openbao://|bearer +[a-z0-9._-]{10,}|password *[:=])'"),
     four_eyes("prompt_version", "decided_by", "created_by", "submitted_by"),
