          ("transition", ["status", "DRAFT>PENDING_APPROVAL,PENDING_APPROVAL>DRAFT,PENDING_APPROVAL>ACTIVE,PENDING_APPROVAL>REJECTED,ACTIVE>SUPERSEDED,ACTIVE>RETIRED"]),
