G_GOV.append(T("compliance_export",
    "EN-17-37 Gói bằng chứng tuân thủ và báo cáo sử dụng đã tạo (FR-17-057, 058; BR-17-076, 077): cấu hình, mô hình và phiên bản, kết quả đánh giá, ca đỏ, sổ đăng ký; KHÔNG chứa nội dung hội thoại. Có băm và chữ ký OpenBao; hết hạn tải thì EXPIRED (ERR-17-081).",
    ["export_kind varchar(16) NOT NULL", "state varchar(10) NOT NULL DEFAULT 'GENERATING'", "requested_by varchar(64) NOT NULL", "period_from date", "period_to date", "file_id uuid",
     "sha256 char(64)", "signature_ref varchar(255)", "expires_at timestamptz", "contains_conversation boolean NOT NULL DEFAULT false", "error_code varchar(16)"],
    [fk("compliance_export", "file_id", "file_object"), chk("compliance_export", "kind", "export_kind IN ('COMPLIANCE_PACK', 'USAGE_REPORT')"),
     chk("compliance_export", "state", f"state IN {E('ExportState')}"), chk("compliance_export", "no_content", "NOT contains_conversation"),
     chk("compliance_export", "period", "period_to IS NULL OR period_from IS NULL OR (period_to >= period_from AND period_to <= period_from + 92)"),
     chk("compliance_export", "ready", "state NOT IN ('READY') OR (file_id IS NOT NULL AND sha256 IS NOT NULL AND signature_ref IS NOT NULL AND expires_at IS NOT NULL)"),
     chk("compliance_export", "sha", "sha256 IS NULL OR sha256 ~ '^[0-9a-f]{64}$'"), chk("compliance_export", "failed", "state <> 'FAILED' OR error_code IS NOT NULL")],
    idx=[f"CREATE INDEX ix_compliance_export_state ON {S}.compliance_export (tenant_id, state, created_at DESC);"],
    tid=True, trig=[("transition", ["state", "GENERATING>READY,GENERATING>FAILED,READY>EXPIRED"])],
    ccomment={"signature_ref": "Tham chiếu chữ ký OpenBao transit; không chứa khóa.", "contains_conversation": "Luôn sai: gói không mang nội dung hội thoại."}))

